import java.util.*;
import static java.util.List.copyOf;

@Builder
public record Document(
    long applicantDocumentId,
    String applicantName,
    List<File> files // bad 1
) {}

record BadRecord(String name, List<String> list) { // bad 2, possibly mutable List exposed
}

record GoodRecord(String name, List<String> list) {
  public GoodRecord {
    list = List.copyOf(list); // good, immutable list
  }
}

record SetRecord(String name, Set<String> set) { // bad 3
}

record BadRecordNonCompact(String name, List<String> list) { // bad 4
  public BadRecordNonCompact(String name, List<String> list) {
    this.name = name;
    this.list = order(list); // bad, no copy
  }
}

record MapRecord(String name, Map<String,String> map) {
    public MapRecord {
        map = Map.copyOf(map); // good
    }
}

record GoodRecordStaticImport(String name, List<String> list) {
  public GoodRecordStaticImport {
    list = copyOf(list); // good, immutable list
  }
}

record GoodRecordNullable(String name, @Nullable List<String> list) {
    public GoodRecordNullable {
        if (list != null) {
            list = List.copyOf(list);
        }
    }
}

record GoodRecordNotNull(String name, @NotNull List<String> list) {
    public GoodRecordNotNull {
        list = List.copyOf(list);
    }
}

record GoodRecordNonNull(String name, @NonNull List<String> list) {
    public GoodRecordNonNull {
        list = List.copyOf(list);
    }
}

record GoodRecordTernary(String name, List<String> list) {
    public GoodRecordTernary {
        list = (list == null) ? null : List.copyOf(list); // keep the state null when null is supplied.
    }
}

record GoodRecordIf(String name, List<String> list) {
    public GoodRecordIf {
        if (list == null) {
            list = null; // keep the state null when null is supplied.
        }
        else {
            list = List.copyOf(list);
        }
    }
}

record GoodRecordNonCompact(String name, List<String> list) {
    public GoodRecordNonCompact(String name, List<String> list) {
        this.name = name;
        if (list == null) {
            this.list = null; // keep the state null when null is supplied.
        }
        else {
            this.list = List.copyOf(list);
        }
    }
}

import java.util.List;

public record MyRecord(List<SomeOtherRecord> otherRecords) { // bad, no copy
    public MyRecord(List<OtherRecord> otherRecords) {
        this.otherRecords = nonNull(otherRecords);
    }
    private static <T> List<T> nonNull(List<T> source) {
        return source == null ? List.of() : source;
    }
}

public record MyRecord(List<SomeOtherRecord> otherRecords) { // good, copy
    public MyRecord(List<OtherRecord> otherRecords) {
        this.otherRecords = nullSafeCopyOf(otherRecords);
    }

    private static <T> List<T> nullSafeCopyOf(List<T> source) {
        if (source != null) {
            return List.copyOf(source);
        } else {
            return List.of();
        }
    }
}

import java.util.List;
import lombok.Builder;

@Builder
public record FooDto(
    List<SomeDto> someDates, // <-- false positive
    List<OtherDto> otherDates  // <-- false positive
){
    public FooDto {
        someDates = List.copyOf(someDates == null ? List.of() : someDates);
        otherDates = List.copyOf(otherDates == null ? List.of() : otherDates);
    }
}
